function renderDockedStepsList() {
    const container = document.getElementById('dockedStepsList');
    const title = document.getElementById('dockedRouteTitle');
    const sub = document.getElementById('dockedRouteSub');
    const selected = activeComputedRoutes.find(r => r.id === selectedRouteId) || activeComputedRoutes[0];
    if (!container || !selected) return;

    if (title) title.innerText = selected.title;
    if (sub) sub.innerText = `${selected.distance} • ${selected.duration}`;

    container.innerHTML = selected.directions.map((step, idx) => {
        return `<div id="dockedStepItem-${idx}" class="docked-step-item p-2.5 rounded-xl bg-slate-50 border border-slate-200 transition-all duration-200 flex items-start gap-2.5">
            <div class="step-icon-box w-7 h-7 rounded-lg bg-blue-100 text-blue-800 flex items-center justify-center shrink-0 mt-0.5 transition-colors">
                <i data-lucide="${step.icon || 'arrow-up'}" class="w-4 h-4"></i>
            </div>
            <div class="flex-1 min-w-0">
                <div class="flex items-center justify-between gap-1">
                    <b class="step-action text-slate-900 block text-xs leading-snug truncate">${step.action}</b>
                    <span id="stepBadge-${idx}" class="hidden text-[9px] font-bold px-1.5 py-0.2 rounded-md bg-emerald-600 text-white shrink-0">ACTIVE</span>
                </div>
                <span class="text-[11px] text-slate-500 block mt-0.5 truncate">${step.detail}</span>
            </div>
        </div>`;
    }).join('');
    lucide.createIcons();
}

function copyDirectionsText() {
    const selected = activeComputedRoutes.find(r => r.id === selectedRouteId) || activeComputedRoutes[0];
    if (!selected) return;
    const text = selected.directions.map((s, idx) => `${idx + 1}. ${s.action} (${s.detail})`).join('\n');
    navigator.clipboard.writeText(text).then(() => {
        alert('Route directions copied to clipboard!');
    }).catch(() => {});
}

function toggleVoiceDirections() {
    if (!('speechSynthesis' in window)) {
        alert('Text-to-speech is not supported in this browser.');
        return;
    }
    if (voiceSynthSpeaking) {
        window.speechSynthesis.cancel();
        voiceSynthSpeaking = false;
        const icon = document.getElementById('voiceNavIcon');
        if (icon) icon.setAttribute('data-lucide', 'volume-2');
        lucide.createIcons();
        return;
    }

    const selected = activeComputedRoutes.find(r => r.id === selectedRouteId) || activeComputedRoutes[0];
    if (!selected) return;

    const speechText = `Starting road directions for ${selected.title}. Total distance ${selected.distance}. First step: ${selected.directions[0].action}.`;
    const utterance = new SpeechSynthesisUtterance(speechText);
    utterance.lang = 'en-IN';
    utterance.rate = 1.0;

    utterance.onend = () => {
        voiceSynthSpeaking = false;
        const icon = document.getElementById('voiceNavIcon');
        if (icon) icon.setAttribute('data-lucide', 'volume-2');
        lucide.createIcons();
    };

    window.speechSynthesis.speak(utterance);
    voiceSynthSpeaking = true;
    const icon = document.getElementById('voiceNavIcon');
    if (icon) icon.setAttribute('data-lucide', 'volume-x');
    lucide.createIcons();
}

