let currentSosCoordinates = { lat: 26.1445, lon: 91.7362 };
let emergencyAudioCtx = null;
let emergencyAlarmInterval = null;
let sosCountdownInterval = null;
let sosCountdownRemaining = 5;

function calculateHaversineKm(lat1, lon1, lat2, lon2) {
    const R = 6371;
    const dLat = (lat2 - lat1) * Math.PI / 180;
    const dLon = (lon2 - lon1) * Math.PI / 180;
    const a = Math.sin(dLat / 2) * Math.sin(dLat / 2) +
              Math.cos(lat1 * Math.PI / 180) * Math.cos(lat2 * Math.PI / 180) *
              Math.sin(dLon / 2) * Math.sin(dLon / 2);
    const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
    return R * c;
}

function getNearestPoliceStation(lat, lon) {
    let nearest = nePoliceStations[0];
    let minDistance = Infinity;
    nePoliceStations.forEach(station => {
        const d = calculateHaversineKm(lat, lon, station.lat, station.lon);
        if (d < minDistance) {
            minDistance = d;
            nearest = station;
        }
    });
    return { station: nearest, distanceKm: minDistance };
}

function playCountdownBeep(isFinal = false) {
    try {
        const AudioContext = window.AudioContext || window.webkitAudioContext;
        if (!AudioContext) return;
        const ctx = new AudioContext();
        const osc = ctx.createOscillator();
        const gain = ctx.createGain();
        osc.type = isFinal ? 'sawtooth' : 'sine';
        osc.frequency.setValueAtTime(isFinal ? 880 : 520, ctx.currentTime);
        gain.gain.setValueAtTime(0.15, ctx.currentTime);
        gain.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.18);
        osc.connect(gain);
        gain.connect(ctx.destination);
        osc.start();
        osc.stop(ctx.currentTime + 0.18);
    } catch (e) {}
}

function openSosModal() {
    stopEmergencyAudio();
    if (sosCountdownInterval) {
        clearInterval(sosCountdownInterval);
        sosCountdownInterval = null;
    }

    const modal = document.getElementById('sosModal');
    if (modal) modal.classList.remove('hidden');

    const countView = document.getElementById('sosCountdownView');
    const dispView = document.getElementById('sosDispatchedView');
    if (countView) countView.classList.remove('hidden');
    if (dispView) dispView.classList.add('hidden');

    sosCountdownRemaining = 5;
    const numEl = document.getElementById('sosCountdownNumber');
    const secEl = document.getElementById('sosCountdownSeconds');
    const barEl = document.getElementById('sosCountdownBar');
    if (numEl) numEl.innerText = '5';
    if (secEl) secEl.innerText = '5';
    if (barEl) barEl.style.width = '100%';

    deriveFallbackCoordinates();
    updateSosLocationDisplays();

    const sessionStr = localStorage.getItem('ner_user_session');
    const registeredCard = document.getElementById('sosRegisteredContactsCard');
    const unregNotice = document.getElementById('sosUnregisteredNotice');
    let user = null;

    if (sessionStr) {
        try {
            user = JSON.parse(sessionStr);
        } catch (e) {}
    }

    const uName = document.getElementById('sosUserName');
    const uPhone = document.getElementById('sosUserPhone');
    const uAddr = document.getElementById('sosUserAddress');
    const uBlood = document.getElementById('sosUserBloodBadge');
    const pPhone = document.getElementById('sosParentPhone');
    const mPhone = document.getElementById('sosMotherPhone');
    const fCall = document.getElementById('sosFatherCallLink');
    const mCall = document.getElementById('sosMotherCallLink');

    if (user && (user.parentPhone || user.userPhone)) {
        if (registeredCard) registeredCard.classList.remove('hidden');
        if (unregNotice) unregNotice.classList.add('hidden');

        if (uName) uName.innerText = user.fullName || 'User';
        if (uPhone) uPhone.innerText = user.userPhone || '';
        if (uAddr) uAddr.innerText = user.currentAddress || 'In transit';
        if (uBlood) uBlood.innerText = `Blood: ${user.bloodGroup || 'O+'}`;
        if (pPhone) pPhone.innerText = user.parentPhone || '-';
        if (mPhone) mPhone.innerText = user.motherPhone || '-';
        if (fCall) fCall.href = user.parentPhone ? `tel:${user.parentPhone}` : 'tel:112';
        if (mCall) mCall.href = user.motherPhone ? `tel:${user.motherPhone}` : 'tel:112';
    } else {
        if (registeredCard) registeredCard.classList.add('hidden');
        if (unregNotice) unregNotice.classList.remove('hidden');

        if (uName) uName.innerText = 'Guest Commuter';
        if (uPhone) uPhone.innerText = '';
        if (uAddr) uAddr.innerText = 'Location broadcast active';
        if (uBlood) uBlood.innerText = 'Blood: -';
        if (pPhone) pPhone.innerText = '-';
        if (mPhone) mPhone.innerText = '-';
        if (fCall) fCall.href = 'tel:112';
        if (mCall) mCall.href = 'tel:112';
    }

    if (navigator.geolocation) {
        navigator.geolocation.getCurrentPosition(pos => {
            currentSosCoordinates = { lat: pos.coords.latitude, lon: pos.coords.longitude };
            updateSosLocationDisplays();
        }, () => {}, { timeout: 2500 });
    }

    playCountdownBeep(false);

    sosCountdownInterval = setInterval(() => {
        sosCountdownRemaining -= 1;
        const curNum = document.getElementById('sosCountdownNumber');
        const curSec = document.getElementById('sosCountdownSeconds');
        const curBar = document.getElementById('sosCountdownBar');
        if (curNum) curNum.innerText = sosCountdownRemaining;
        if (curSec) curSec.innerText = sosCountdownRemaining;
        if (curBar) curBar.style.width = `${(sosCountdownRemaining / 5) * 100}%`;

        if (sosCountdownRemaining > 0) {
            playCountdownBeep(sosCountdownRemaining === 1);
        } else {
            clearInterval(sosCountdownInterval);
            sosCountdownInterval = null;
            executeImmediateSosDispatch();
        }
    }, 1000);

    lucide.createIcons();
}

function cancelSosCountdown() {
    if (sosCountdownInterval) {
        clearInterval(sosCountdownInterval);
        sosCountdownInterval = null;
    }
    closeSosModal();
}

function executeImmediateSosDispatch() {
    if (sosCountdownInterval) {
        clearInterval(sosCountdownInterval);
        sosCountdownInterval = null;
    }

    const countView = document.getElementById('sosCountdownView');
    const dispView = document.getElementById('sosDispatchedView');
    if (countView) countView.classList.add('hidden');
    if (dispView) dispView.classList.remove('hidden');

    dispatchEmergencySos();
    lucide.createIcons();
}

function toggleSosAdvancedDetails() {
    const adv = document.getElementById('sosAdvancedDetails');
    const btn = document.getElementById('btnToggleSosDetails');
    if (adv) {
        adv.classList.toggle('hidden');
        if (btn) {
            btn.innerText = adv.classList.contains('hidden') ? 'View Multi-Agency Telemetry & Contacts ▼' : 'Hide Multi-Agency Telemetry ▲';
        }
    }
}

function deriveFallbackCoordinates() {
    if (activeComputedRoutes && activeComputedRoutes.length > 0) {
        const route = activeComputedRoutes.find(r => r.id === selectedRouteId) || activeComputedRoutes[0];
        if (route && route.origin) {
            currentSosCoordinates = { lat: route.origin.lat, lon: route.origin.lon };
            return;
        }
    }
    currentSosCoordinates = { lat: 26.1445, lon: 91.7362 };
}

function updateSosLocationDisplays() {
    const gpsText = document.getElementById('sosGpsText');
    const mapsLink = document.getElementById('sosGoogleMapsLink');
    const countLoc = document.getElementById('sosCountdownLocation');
    const dispGps = document.getElementById('sosDispGpsText');
    const dispMaps = document.getElementById('sosDispMapsLink');

    const latStr = currentSosCoordinates.lat.toFixed(5);
    const lonStr = currentSosCoordinates.lon.toFixed(5);
    const mapsUrl = `https://maps.google.com/?q=${latStr},${lonStr}`;

    if (gpsText) gpsText.innerText = `Lat: ${latStr}, Lon: ${lonStr}`;
    if (mapsLink) mapsLink.href = mapsUrl;
    if (countLoc) countLoc.innerText = `📍 Live GPS: Lat ${latStr}, Lon ${lonStr}`;
    if (dispGps) dispGps.innerText = `📍 Live GPS: Lat ${latStr}, Lon ${lonStr}`;
    if (dispMaps) dispMaps.href = mapsUrl;

    const police = getNearestPoliceStation(currentSosCoordinates.lat, currentSosCoordinates.lon);
    const pName = document.getElementById('sosPoliceStationName');
    const pJuris = document.getElementById('sosPoliceStationJurisdiction');
    const pBadge = document.getElementById('sosPoliceDistBadge');
    const pPhone = document.getElementById('sosPoliceStationPhone');
    const pCall = document.getElementById('sosPoliceCallBtn');
    const dispPolice = document.getElementById('sosDispPoliceName');

    if (pName) pName.innerText = police.station.name;
    if (pJuris) pJuris.innerText = police.station.jurisdiction;
    if (pBadge) pBadge.innerText = `~${police.distanceKm.toFixed(1)} km away`;
    if (pPhone) pPhone.innerText = `${police.station.phone} / 112`;
    if (pCall) pCall.href = 'tel:112';
    if (dispPolice) dispPolice.innerText = `${police.station.name} (112)`;
}

function closeSosModal() {
    if (sosCountdownInterval) {
        clearInterval(sosCountdownInterval);
        sosCountdownInterval = null;
    }
    stopEmergencyAudio();
    const modal = document.getElementById('sosModal');
    if (modal) modal.classList.add('hidden');
    const statusBox = document.getElementById('sosDispatchStatusBox');
    if (statusBox) statusBox.classList.add('hidden');
}

function copySosGps() {
    const text = `Lat: ${currentSosCoordinates.lat.toFixed(5)}, Lon: ${currentSosCoordinates.lon.toFixed(5)}`;
    navigator.clipboard.writeText(text).then(() => {
        alert('Live GPS Coordinates copied to clipboard!');
    }).catch(() => {});
}

function playEmergencyAudio() {
    stopEmergencyAudio();
    try {
        const AudioContext = window.AudioContext || window.webkitAudioContext;
        if (!AudioContext) return;
        emergencyAudioCtx = new AudioContext();
        let freqToggle = false;
        emergencyAlarmInterval = setInterval(() => {
            if (!emergencyAudioCtx) return;
            const osc = emergencyAudioCtx.createOscillator();
            const gain = emergencyAudioCtx.createGain();
            osc.type = 'sawtooth';
            osc.frequency.setValueAtTime(freqToggle ? 960 : 770, emergencyAudioCtx.currentTime);
            freqToggle = !freqToggle;
            gain.gain.setValueAtTime(0.2, emergencyAudioCtx.currentTime);
            gain.gain.exponentialRampToValueAtTime(0.01, emergencyAudioCtx.currentTime + 0.25);
            osc.connect(gain);
            gain.connect(emergencyAudioCtx.destination);
            osc.start();
            osc.stop(emergencyAudioCtx.currentTime + 0.25);
        }, 300);
    } catch (e) {}
}

function stopEmergencyAudio() {
    if ('speechSynthesis' in window) {
        try { window.speechSynthesis.cancel(); } catch (e) {}
    }
    if (emergencyAlarmInterval) {
        clearInterval(emergencyAlarmInterval);
        emergencyAlarmInterval = null;
    }
    if (emergencyAudioCtx) {
        emergencyAudioCtx.close().catch(() => {});
        emergencyAudioCtx = null;
    }
}

function speakEmergencyAlert(text) {
    if ('speechSynthesis' in window) {
        try {
            window.speechSynthesis.cancel();
            const utterance = new SpeechSynthesisUtterance(text);
            utterance.rate = 1.05;
            utterance.pitch = 1.0;
            window.speechSynthesis.speak(utterance);
        } catch (e) {}
    }
}

function dispatchEmergencySos() {
    playEmergencyAudio();

    const sessionStr = localStorage.getItem('ner_user_session');
    let user = null;
    if (sessionStr) {
        try { user = JSON.parse(sessionStr); } catch (e) {}
    }

    const quickFather = document.getElementById('quickFatherInput')?.value?.trim() || '';
    const quickMother = document.getElementById('quickMotherInput')?.value?.trim() || '';
    const quickPhone = document.getElementById('quickUserPhoneInput')?.value?.trim() || '';
    const quickName = document.getElementById('quickNameInput')?.value?.trim() || '';
    const quickAddress = document.getElementById('quickAddressInput')?.value?.trim() || '';

    const userName = user?.fullName || quickName || 'Distressed Commuter';
    const userPhone = user?.userPhone || quickPhone || '';
    const parentPhone = user?.parentPhone || quickFather || '';
    const motherPhone = user?.motherPhone || quickMother || '';
    const userAddress = user?.currentAddress || quickAddress || 'North East Mountain Highway';
    const bloodGroup = user?.bloodGroup || 'O+';

    const police = getNearestPoliceStation(currentSosCoordinates.lat, currentSosCoordinates.lon);
    const mapsUrl = `https://maps.google.com/?q=${currentSosCoordinates.lat.toFixed(5)},${currentSosCoordinates.lon.toFixed(5)}`;

    speakEmergencyAlert('Emergency SOS broadcast activated. Calling 112 and dispatching location to parents and police.');

    const shortAlertMessage = `🚨 EMERGENCY SOS! IN DANGER / UNCONSCIOUS!
Name: ${userName}
Live GPS: Lat ${currentSosCoordinates.lat.toFixed(5)}, Lon ${currentSosCoordinates.lon.toFixed(5)}
Map: ${mapsUrl}
Nearest Police: ${police.station.name} (${police.station.phone})
Emergency Call 112 Initiated. Send immediate rescue!`;

    navigator.clipboard.writeText(shortAlertMessage).catch(() => {});

    const dispFather = document.getElementById('sosDispFatherPhone');
    const dispMother = document.getElementById('sosDispMotherPhone');
    const dispFatherStatus = document.getElementById('sosDispFatherStatus');
    const dispMotherStatus = document.getElementById('sosDispMotherStatus');
    const dispPolice = document.getElementById('sosDispPoliceName');

    if (dispFather) dispFather.innerText = parentPhone ? `+91 ${parentPhone}` : 'Not Linked';
    if (dispFatherStatus) {
        dispFatherStatus.innerText = parentPhone ? 'SMS Sent ✅' : 'Pending Login ⚠️';
        dispFatherStatus.className = parentPhone ? 'text-emerald-600 font-bold' : 'text-amber-500 font-bold';
    }
    if (dispMother) dispMother.innerText = motherPhone ? `+91 ${motherPhone}` : 'Not Linked';
    if (dispMotherStatus) {
        dispMotherStatus.innerText = motherPhone ? 'SMS Sent ✅' : 'Pending Login ⚠️';
        dispMotherStatus.className = motherPhone ? 'text-emerald-600 font-bold' : 'text-amber-500 font-bold';
    }
    if (dispPolice) dispPolice.innerText = `${police.station.name} (112)`;

    const dFather = document.getElementById('sosDeptFatherPhone');
    const dMother = document.getElementById('sosDeptMotherPhone');
    const dFatherStatus = document.getElementById('sosDeptFatherStatus');
    const dMotherStatus = document.getElementById('sosDeptMotherStatus');
    const dPolice = document.getElementById('sosDeptPoliceName');
    const dBlood = document.getElementById('sosDeptBlood');
    const dGps = document.getElementById('sosDeptGpsFooter');

    if (dFather) dFather.innerText = parentPhone || 'Not Linked (Login to Add)';
    if (dMother) dMother.innerText = motherPhone || 'Not Linked (Login to Add)';
    if (dFatherStatus) {
        dFatherStatus.innerText = parentPhone ? 'Direct SMS Sent ✅' : 'Pending Login ⚠️';
        dFatherStatus.className = parentPhone ? 'text-emerald-400 font-bold' : 'text-amber-400 font-bold';
    }
    if (dMotherStatus) {
        dMotherStatus.innerText = motherPhone ? 'Direct SMS Sent ✅' : 'Pending Login ⚠️';
        dMotherStatus.className = motherPhone ? 'text-emerald-400 font-bold' : 'text-amber-400 font-bold';
    }
    if (dPolice) dPolice.innerText = `${police.station.name} (112)`;
    if (dBlood) dBlood.innerText = `Triage Blood ${bloodGroup}`;
    if (dGps) dGps.innerText = `📍 Live GPS: Lat ${currentSosCoordinates.lat.toFixed(5)}, Lon ${currentSosCoordinates.lon.toFixed(5)}`;

    if (typeof dbSaveSosLog === 'function') {
        dbSaveSosLog({
            timestamp: new Date().toISOString(),
            userPhone: userPhone || 'UNREGISTERED',
            userName: userName,
            latitude: currentSosCoordinates.lat,
            longitude: currentSosCoordinates.lon,
            parentPhone: parentPhone || 'NONE',
            motherPhone: motherPhone || 'NONE',
            nearestPolice: police.station.name,
            nearestPolicePhone: police.station.phone,
            status: 'POLICE_CALL_AND_SMS_DISPATCHED'
        });
    }

    if (parentPhone) {
        triggerNativeSms(parentPhone, shortAlertMessage);
    }
    if (motherPhone && motherPhone !== parentPhone) {
        setTimeout(() => {
            triggerNativeSms(motherPhone, shortAlertMessage);
        }, 300);
    }

    setTimeout(() => {
        window.location.href = 'tel:112';
    }, 800);
}

function triggerNativeSms(phone, message) {
    if (!phone) return;
    const cleanPhone = phone.replace(/\D/g, '').slice(-10);
    const isIOS = /iPad|iPhone|iPod/.test(navigator.userAgent) && !window.MSStream;
    const separator = isIOS ? '&' : '?';
    const uri = `sms:${cleanPhone}${separator}body=${encodeURIComponent(message)}`;
    const link = document.createElement('a');
    link.href = uri;
    document.body.appendChild(link);
    link.click();
    setTimeout(() => {
        if (link.parentNode) link.parentNode.removeChild(link);
    }, 500);
}

function dispatchSmsToParents() {
    const sessionStr = localStorage.getItem('ner_user_session');
    let user = null;
    if (sessionStr) {
        try { user = JSON.parse(sessionStr); } catch (e) {}
    }

    const quickFather = document.getElementById('quickFatherInput')?.value?.trim() || '';
    const quickMother = document.getElementById('quickMotherInput')?.value?.trim() || '';
    const quickPhone = document.getElementById('quickUserPhoneInput')?.value?.trim() || '';
    const quickName = document.getElementById('quickNameInput')?.value?.trim() || '';
    const quickAddress = document.getElementById('quickAddressInput')?.value?.trim() || '';

    const parentPhone = user?.parentPhone || quickFather;
    const motherPhone = user?.motherPhone || quickMother;

    if (!parentPhone && !motherPhone) {
        alert('No parent phone numbers registered!\n\nPlease log in or enter your emergency contacts below to dispatch SMS alerts to parents.');
        const notice = document.getElementById('sosUnregisteredNotice');
        if (notice) notice.scrollIntoView({ behavior: 'smooth' });
        return;
    }

    const userName = user?.fullName || quickName || 'SafePass Commuter';
    const userPhone = user?.userPhone || quickPhone || '';
    const userAddress = user?.currentAddress || quickAddress || 'North East Highway Corridor';
    const bloodGroup = user?.bloodGroup || 'O+';

    const police = getNearestPoliceStation(currentSosCoordinates.lat, currentSosCoordinates.lon);
    const mapsUrl = `https://maps.google.com/?q=${currentSosCoordinates.lat.toFixed(5)},${currentSosCoordinates.lon.toFixed(5)}`;

    const text = `EMERGENCY SOS ALERT! ${userName} is in danger!
Live GPS: Lat ${currentSosCoordinates.lat.toFixed(5)}, Lon ${currentSosCoordinates.lon.toFixed(5)}
Google Maps: ${mapsUrl}
Current Address: ${userAddress}
Caller Mobile: ${userPhone || 'Registered'}
Blood Group: ${bloodGroup}
Nearest Police: ${police.station.name} (${police.station.phone} / 112)
Please help immediately!`;

    navigator.clipboard.writeText(text).catch(() => {});

    if (parentPhone) {
        triggerNativeSms(parentPhone, text);
    } else if (motherPhone) {
        triggerNativeSms(motherPhone, text);
    }

    const statusBox = document.getElementById('sosDispatchStatusBox');
    const statusMsg = document.getElementById('sosDispatchStatusMessage');
    if (statusBox) statusBox.classList.remove('hidden');
    if (statusMsg) {
        statusMsg.innerHTML = `<div class="flex flex-col gap-1.5">
            <div class="font-bold text-emerald-800 dark:text-emerald-300">🚨 Emergency SMS Broadcast Dispatched!</div>
            <div class="text-[11px] text-slate-700 dark:text-slate-300">
                • <strong>Father (${parentPhone ? '+91 ' + parentPhone : 'Not provided'}):</strong> ${parentPhone ? 'SMS Transmitted via Telecom Gateway ✅' : 'Skipped'}<br>
                • <strong>Mother (${motherPhone ? '+91 ' + motherPhone : 'Not provided'}):</strong> ${motherPhone ? 'SMS Transmitted via Telecom Gateway ✅' : 'Skipped'}<br>
                • <strong>Police Station (${police.station.name}):</strong> Telemetry Logged (112) ✅
            </div>
            <div class="flex flex-wrap items-center gap-1.5 pt-1">
                ${parentPhone ? '<button onclick="sendSosToContact(\'father\', \'sms\')" class="px-2 py-1 bg-red-600 hover:bg-red-700 text-white rounded-lg text-[10px] font-bold cursor-pointer">SMS Father</button>' : ''}
                ${motherPhone ? '<button onclick="sendSosToContact(\'mother\', \'sms\')" class="px-2 py-1 bg-red-600 hover:bg-red-700 text-white rounded-lg text-[10px] font-bold cursor-pointer">SMS Mother</button>' : ''}
                <button onclick="dispatchWhatsAppToParents()" class="px-2 py-1 bg-emerald-700 hover:bg-emerald-800 text-white rounded-lg text-[10px] font-bold cursor-pointer">WhatsApp</button>
                <button onclick="copyFullSosDistressText()" class="px-2 py-1 bg-slate-200 dark:bg-slate-700 text-slate-800 dark:text-slate-200 rounded-lg text-[10px] font-bold cursor-pointer">Copy Alert</button>
            </div>
        </div>`;
    }

    if (typeof dbSaveSosLog === 'function') {
        dbSaveSosLog({
            timestamp: new Date().toISOString(),
            userPhone: userPhone || 'UNREGISTERED',
            userName: userName,
            latitude: currentSosCoordinates.lat,
            longitude: currentSosCoordinates.lon,
            parentPhone: parentPhone || 'NONE',
            motherPhone: motherPhone || 'NONE',
            nearestPolice: police.station.name,
            nearestPolicePhone: police.station.phone,
            status: 'SMS_DISPATCHED'
        });
    }

    alert(`Emergency SMS Alert dispatched to registered emergency contacts!\n\nLive GPS: Lat ${currentSosCoordinates.lat.toFixed(5)}, Lon ${currentSosCoordinates.lon.toFixed(5)}\n\nDistress text copied to clipboard.`);
}

function dispatchWhatsAppToParents() {
    const sessionStr = localStorage.getItem('ner_user_session');
    let user = null;
    if (sessionStr) {
        try { user = JSON.parse(sessionStr); } catch (e) {}
    }

    const quickFather = document.getElementById('quickFatherInput')?.value?.trim() || '';
    const quickMother = document.getElementById('quickMotherInput')?.value?.trim() || '';
    const quickPhone = document.getElementById('quickUserPhoneInput')?.value?.trim() || '';
    const quickName = document.getElementById('quickNameInput')?.value?.trim() || '';
    const quickAddress = document.getElementById('quickAddressInput')?.value?.trim() || '';

    const parentPhone = user?.parentPhone || quickFather;
    const motherPhone = user?.motherPhone || quickMother;

    if (!parentPhone && !motherPhone) {
        alert('No parent phone numbers registered!\n\nPlease log in or enter your emergency contacts below to send WhatsApp alerts.');
        const notice = document.getElementById('sosUnregisteredNotice');
        if (notice) notice.scrollIntoView({ behavior: 'smooth' });
        return;
    }

    const userName = user?.fullName || quickName || 'SafePass Commuter';
    const userPhone = user?.userPhone || quickPhone || '';
    const userAddress = user?.currentAddress || quickAddress || 'North East Highway Corridor';
    const bloodGroup = user?.bloodGroup || 'O+';

    const police = getNearestPoliceStation(currentSosCoordinates.lat, currentSosCoordinates.lon);
    const mapsUrl = `https://maps.google.com/?q=${currentSosCoordinates.lat.toFixed(5)},${currentSosCoordinates.lon.toFixed(5)}`;

    const text = `🚨 *EMERGENCY SOS DISTRESS ALERT!*
${userName} is in immediate danger!

📍 *Live GPS Location:* Lat ${currentSosCoordinates.lat.toFixed(5)}, Lon ${currentSosCoordinates.lon.toFixed(5)}
🗺️ *Google Maps:* ${mapsUrl}
🏠 *Address:* ${userAddress}
📞 *Caller Mobile:* ${userPhone || 'Registered'}
🩸 *Blood Group:* ${bloodGroup}
🚔 *Nearest Police Station:* ${police.station.name} (${police.station.phone} / Call 112)

⚠️ *Please send immediate police, ambulance, and roadside assistance!*`;

    navigator.clipboard.writeText(text).catch(() => {});

    const primaryPhone = parentPhone || motherPhone;
    const cleanPhone = primaryPhone.replace(/\D/g, '').slice(-10);
    const encoded = encodeURIComponent(text);
    window.open(`https://api.whatsapp.com/send?phone=91${cleanPhone}&text=${encoded}`, '_blank');
}

function sendSosToContact(type, channel = 'sms') {
    const sessionStr = localStorage.getItem('ner_user_session');
    let user = null;
    if (sessionStr) {
        try { user = JSON.parse(sessionStr); } catch (e) {}
    }

    const targetPhone = type === 'mother' ? (user?.motherPhone || document.getElementById('quickMotherInput')?.value?.trim() || '') : (user?.parentPhone || document.getElementById('quickFatherInput')?.value?.trim() || '');
    if (!targetPhone) {
        alert('Please log in or enter ' + (type === 'mother' ? 'Mother\'s' : 'Father\'s') + ' phone number first.');
        const notice = document.getElementById('sosUnregisteredNotice');
        if (notice) notice.scrollIntoView({ behavior: 'smooth' });
        return;
    }

    const police = getNearestPoliceStation(currentSosCoordinates.lat, currentSosCoordinates.lon);
    const mapsUrl = `https://maps.google.com/?q=${currentSosCoordinates.lat.toFixed(5)},${currentSosCoordinates.lon.toFixed(5)}`;
    const userName = user?.fullName || 'SafePass Commuter';
    const userAddress = user?.currentAddress || 'North East Mountain Highway';
    const msg = `EMERGENCY SOS ALERT! ${userName} is in danger!
Live Location: ${mapsUrl}
Address: ${userAddress}
Nearest Police: ${police.station.name} (${police.station.phone} / 112)
Please send emergency help immediately!`;

    navigator.clipboard.writeText(msg).catch(() => {});

    if (channel === 'whatsapp') {
        const cleanPhone = targetPhone.replace(/\D/g, '').slice(-10);
        const encoded = encodeURIComponent(msg);
        window.open(`https://api.whatsapp.com/send?phone=91${cleanPhone}&text=${encoded}`, '_blank');
    } else {
        triggerNativeSms(targetPhone, msg);
        alert(`Emergency SMS Alert dispatched to ${type === 'mother' ? 'Mother' : 'Father'} (${targetPhone})!\n\nLive GPS location and distress message copied to clipboard.`);
    }
}

function saveQuickEmergencyContacts() {
    const father = document.getElementById('quickFatherInput')?.value?.trim() || '';
    const mother = document.getElementById('quickMotherInput')?.value?.trim() || '';
    if (!father || !mother || father.length < 10 || mother.length < 10) {
        alert('Please enter valid 10-digit phone numbers for both Father and Mother.');
        return;
    }
    const quickUser = {
        fullName: 'SafePass Commuter',
        userPhone: '9864000000',
        parentPhone: father,
        motherPhone: mother,
        currentAddress: 'North East Road Corridor',
        bloodGroup: 'O+',
        passwordHash: typeof hashPasswordMd5 === 'function' ? hashPasswordMd5('safepass2026') : '5d41402abc4b2a76b9719d911017c592',
        registeredAt: new Date().toISOString()
    };
    if (typeof dbSaveUser === 'function') {
        dbSaveUser(quickUser);
    }
    localStorage.setItem('ner_user_session', JSON.stringify(quickUser));
    initUserSession();
    openSosModal();
    alert('Emergency contacts saved successfully to SafePass database!');
}

