function initUserSession() {
    const sessionStr = localStorage.getItem('ner_user_session');
    const loginBtn = document.getElementById('headerLoginBtn');
    const profileMenu = document.getElementById('headerUserProfileMenu');
    const nameText = document.getElementById('headerUserNameText');
    const dropName = document.getElementById('dropdownFullName');
    const dropPhone = document.getElementById('dropdownPhone');
    const dropFather = document.getElementById('dropdownFatherPhone');
    const dropMother = document.getElementById('dropdownMotherPhone');

    if (!sessionStr) {
        if (loginBtn) loginBtn.classList.remove('hidden');
        if (profileMenu) profileMenu.classList.add('hidden');
        return;
    }

    try {
        const user = JSON.parse(sessionStr);
        if (loginBtn) loginBtn.classList.add('hidden');
        if (profileMenu) profileMenu.classList.remove('hidden');
        if (nameText) nameText.innerText = (user.fullName || 'User').split(' ')[0];
        if (dropName) dropName.innerText = user.fullName || 'User';
        if (dropPhone) dropPhone.innerText = `+91 ${user.userPhone || ''}`;
        if (dropFather) dropFather.innerText = user.parentPhone || '-';
        if (dropMother) dropMother.innerText = user.motherPhone || '-';
    } catch (e) {
        if (loginBtn) loginBtn.classList.remove('hidden');
        if (profileMenu) profileMenu.classList.add('hidden');
    }
}

function toggleUserDropdown() {
    const menu = document.getElementById('userDropdownMenu');
    if (menu) menu.classList.toggle('hidden');
}

function userLogout() {
    localStorage.removeItem('ner_user_session');
    const menu = document.getElementById('userDropdownMenu');
    if (menu) menu.classList.add('hidden');
    initUserSession();
    const sosModal = document.getElementById('sosModal');
    if (sosModal && !sosModal.classList.contains('hidden')) {
        openSosModal(false);
    }
}

function openLoginModal() {
    const modal = document.getElementById('loginModal');
    if (modal) modal.classList.remove('hidden');
    const errBox = document.getElementById('inPageLoginError');
    if (errBox) errBox.classList.add('hidden');
    lucide.createIcons();
}

function closeLoginModal() {
    const modal = document.getElementById('loginModal');
    if (modal) modal.classList.add('hidden');
}

async function submitInPageLogin(event) {
    if (event) event.preventDefault();
    const phone = document.getElementById('inPageLoginPhone')?.value?.trim() || '';
    const pass = document.getElementById('inPageLoginPass')?.value || '';
    const errBox = document.getElementById('inPageLoginError');
    if (!phone || !pass) return;

    let verifiedUser = null;
    if (typeof dbVerifyUser === 'function') {
        verifiedUser = await dbVerifyUser(phone, pass);
    }
    if (!verifiedUser) {
        const stored = getUserFromLocalStorage(phone);
        const hashed = typeof hashPasswordMd5 === 'function' ? hashPasswordMd5(pass) : pass;
        if (stored && (stored.passwordHash === hashed || stored.password === pass)) {
            verifiedUser = stored;
        }
    }

    if (verifiedUser) {
        localStorage.setItem('ner_user_session', JSON.stringify(verifiedUser));
        initUserSession();
        closeLoginModal();
        const sosModal = document.getElementById('sosModal');
        if (sosModal && !sosModal.classList.contains('hidden')) {
            openSosModal();
        }
        alert(`Welcome back, ${verifiedUser.fullName}! Personal details & emergency contacts connected.`);
    } else {
        if (errBox) {
            errBox.innerText = 'Invalid mobile number or password. Verification failed.';
            errBox.classList.remove('hidden');
        }
    }
}

