async function loginFromSosModal() {
    const phone = (document.getElementById('sosInlinePhone')?.value || document.getElementById('inPageLoginPhone')?.value || '').trim();
    const pass = document.getElementById('sosInlinePass')?.value || document.getElementById('inPageLoginPass')?.value || '';
    if (!phone || !pass) {
        alert('Please enter your registered mobile number and password.');
        return;
    }
    let verifiedUser = null;
    if (typeof dbVerifyUser === 'function') {
        verifiedUser = await dbVerifyUser(phone, pass);
    }
    if (!verifiedUser) {
        const stored = getUserFromLocalStorage(phone);
        const hashed = typeof hashPasswordMd5 === 'function' ? hashPasswordMd5(pass) : pass;
        if (stored && (stored.passwordHash === hashed || stored.password === pass)) {
            verifiedUser = stored;
        }
    }

    if (verifiedUser) {
        localStorage.setItem('ner_user_session', JSON.stringify(verifiedUser));
        initUserSession();
        openSosModal();
        alert(`Personal details and emergency contacts connected for ${verifiedUser.fullName}!`);
    } else {
        alert('Credentials not found. Please verify your phone number and password or click Sign Up.');
    }
}

async function demoLoginFromSosModal() {
    await loginInPageDemoUser();
}

async function saveQuickPersonalDetails() {
    const fullName = document.getElementById('quickNameInput')?.value?.trim() || 'SafePass Commuter';
    const userPhone = document.getElementById('quickUserPhoneInput')?.value?.trim() || '9864000000';
    const fatherPhone = document.getElementById('quickFatherInput')?.value?.trim() || '';
    const motherPhone = document.getElementById('quickMotherInput')?.value?.trim() || '';
    const currentAddress = document.getElementById('quickAddressInput')?.value?.trim() || 'North East Road Corridor';

    if (!fatherPhone || !motherPhone || fatherPhone.length < 10 || motherPhone.length < 10) {
        alert('Please enter valid 10-digit mobile numbers for Father and Mother.');
        return;
    }

    const userData = {
        fullName: fullName,
        userPhone: userPhone,
        parentPhone: fatherPhone,
        motherPhone: motherPhone,
        currentAddress: currentAddress,
        bloodGroup: 'O+',
        passwordHash: typeof hashPasswordMd5 === 'function' ? hashPasswordMd5('safepass2026') : '5d41402abc4b2a76b9719d911017c592',
        registeredAt: new Date().toISOString()
    };

    if (typeof dbSaveUser === 'function') {
        await dbSaveUser(userData);
    }
    localStorage.setItem('ner_user_session', JSON.stringify(userData));
    initUserSession();
    openSosModal();
    alert('Personal details & parents numbers securely stored and connected to SOS!');
}

