function changeLanguage(langKey) {
    if (!translations[langKey]) {
        langKey = 'en';
    }
    try {
        localStorage.setItem('ner_selected_lang', langKey);
    } catch (e) {}
    const langSelect = document.getElementById('languageSelect');
    if (langSelect && langSelect.value !== langKey) {
        langSelect.value = langKey;
    }
    const dict = translations[langKey] || translations.en;
    document.querySelectorAll('[data-i18n]').forEach(el => {
        const key = el.getAttribute('data-i18n');
        if (dict && dict[key] !== undefined) {
            el.innerHTML = dict[key];
        }
    });
    document.querySelectorAll('[data-i18n-placeholder]').forEach(el => {
        const key = el.getAttribute('data-i18n-placeholder');
        if (dict && dict[key] !== undefined) {
            el.setAttribute('placeholder', dict[key]);
        }
    });
    document.querySelectorAll('[data-i18n-title]').forEach(el => {
        const key = el.getAttribute('data-i18n-title');
        if (dict && dict[key] !== undefined) {
            el.setAttribute('title', dict[key]);
        }
    });
    if (window.lucide && typeof window.lucide.createIcons === 'function') {
        window.lucide.createIcons();
    }
    if (typeof activeComputedRoutes !== 'undefined' && activeComputedRoutes && activeComputedRoutes.length > 0) {
        renderRouteCards();
    }
}

function openOfflineCenterModal() {
    const modal = document.getElementById('offlineCenterModal');
    if (modal) modal.classList.remove('hidden');
    renderSavedOfflineRoutesList();
    updateNetworkStatus(!isSimulatedOffline && navigator.onLine);
    lucide.createIcons();
}

function closeOfflineCenterModal() {
    const modal = document.getElementById('offlineCenterModal');
    if (modal) modal.classList.add('hidden');
}

function toggleSimulateSignalCutoff() {
    isSimulatedOffline = !isSimulatedOffline;
    updateNetworkStatus(!isSimulatedOffline && navigator.onLine);
}

function updateNetworkStatus(isOnline) {
    const headerStatus = document.getElementById('headerOfflineStatusText');
    const headerBtn = document.getElementById('btnOfflineCenterHeader');
    const banner = document.getElementById('signalCutoffBanner');
    const dot = document.getElementById('offlineStatusIndicatorDot');
    const title = document.getElementById('modalConnectionStatusTitle');
    const badge = document.getElementById('modalConnectionModeBadge');
    const desc = document.getElementById('modalConnectionStatusDesc');
    const btnSimText = document.getElementById('btnSimulateSignalText');
    const btnSim = document.getElementById('btnToggleSimulateSignal');

    if (!isOnline) {
        if (headerStatus) headerStatus.innerText = 'Offline Active';
        if (headerBtn) {
            headerBtn.className = 'flex items-center gap-1 bg-amber-600 hover:bg-amber-700 text-white px-2.5 py-1.5 rounded-xl text-xs font-bold shadow-xs transition active:scale-95 animate-pulse';
        }
        if (banner) banner.classList.remove('hidden');
        if (dot) dot.className = 'w-3.5 h-3.5 rounded-full bg-amber-500 animate-ping';
        if (title) title.innerText = 'Signal Lost: 100% Offline Mode';
        if (badge) {
            badge.innerText = 'Zero Signal';
            badge.className = 'text-[10px] font-semibold bg-amber-100 text-amber-900 px-2 py-0.5 rounded-full';
        }
        if (desc) desc.innerText = 'Operating purely from device storage & hardware GPS satellite link. No cellular data needed.';
        if (btnSimText) btnSimText.innerText = 'Restore Live Connection';
        if (btnSim) btnSim.className = 'w-full sm:w-auto shrink-0 bg-emerald-600 hover:bg-emerald-700 text-white font-bold text-xs px-3.5 py-2 rounded-xl flex items-center justify-center gap-1.5 shadow-xs transition btn-press';
    } else {
        if (headerStatus) headerStatus.innerText = 'Offline Hub';
        if (headerBtn) {
            headerBtn.className = 'flex items-center gap-1 bg-emerald-600 hover:bg-emerald-700 text-white px-2.5 py-1.5 rounded-xl text-xs font-bold shadow-xs transition active:scale-95';
        }
        if (banner) banner.classList.add('hidden');
        if (dot) dot.className = 'w-3.5 h-3.5 rounded-full bg-emerald-500 animate-pulse';
        if (title) title.innerText = 'Network Signal: Active';
        if (badge) {
            badge.innerText = 'Online';
            badge.className = 'text-[10px] font-semibold bg-emerald-100 text-emerald-800 px-2 py-0.5 rounded-full';
        }
        if (desc) desc.innerText = 'Live OSRM and telemetry available. PWA cached for sudden blackout.';
        if (btnSimText) btnSimText.innerText = 'Simulate Signal Cutoff';
        if (btnSim) btnSim.className = 'w-full sm:w-auto shrink-0 bg-amber-600 hover:bg-amber-700 text-white font-bold text-xs px-3.5 py-2 rounded-xl flex items-center justify-center gap-1.5 shadow-xs transition btn-press';
    }
    lucide.createIcons();
}

function saveRouteToLocalCache(routeArr, origName, destName) {
    if (!routeArr || !Array.isArray(routeArr) || routeArr.length === 0) return;
    try {
        const stored = JSON.parse(localStorage.getItem('ner_cached_routes') || '[]');
        const key = `${origName.toLowerCase()}_to_${destName.toLowerCase()}`;
        const existingIndex = stored.findIndex(e => e.key === key);
        const entry = {
            id: 'corridor_' + Date.now(),
            key: key,
            origin: origName,
            destination: destName,
            title: `${origName} ↔ ${destName}`,
            distance: routeArr[0].distance || '',
            duration: routeArr[0].duration || '',
            safetyScore: routeArr[0].safetyScore || '92/100',
            savedAt: new Date().toLocaleDateString(),
            routes: routeArr
        };
        if (existingIndex >= 0) {
            stored[existingIndex] = entry;
        } else {
            stored.unshift(entry);
            if (stored.length > 10) stored.pop();
        }
        localStorage.setItem('ner_cached_routes', JSON.stringify(stored));
    } catch (e) {}
}

function getCachedRoute(origName, destName) {
    try {
        const stored = JSON.parse(localStorage.getItem('ner_cached_routes') || '[]');
        const oKey = (origName || '').toLowerCase().trim();
        const dKey = (destName || '').toLowerCase().trim();
        const match = stored.find(e => {
            const eO = e.origin.toLowerCase().trim();
            const eD = e.destination.toLowerCase().trim();
            return (eO === oKey && eD === dKey) || (eO === dKey && eD === oKey);
        });
        if (match && match.routes && match.routes.length > 0) {
            return match.routes;
        }
    } catch (e) {}
    return null;
}

function downloadCurrentRouteOffline() {
    if (!activeComputedRoutes || activeComputedRoutes.length === 0) {
        alert('Please select or calculate a route before saving offline.');
        return;
    }
    const current = activeComputedRoutes[0];
    const origName = current.origin ? current.origin.name : (document.getElementById('originInput')?.value?.trim() || 'Guwahati');
    const destName = current.destination ? current.destination.name : (document.getElementById('destinationInput')?.value?.trim() || 'Itanagar');
    saveRouteToLocalCache(activeComputedRoutes, origName, destName);
    renderSavedOfflineRoutesList();
    alert(`Corridor "${origName} to ${destName}" is now fully stored in your device! You can travel freely even if mobile towers lose signal.`);
}

function renderSavedOfflineRoutesList() {
    const listEl = document.getElementById('offlineSavedRoutesList');
    if (!listEl) return;
    try {
        const stored = JSON.parse(localStorage.getItem('ner_cached_routes') || '[]');
        if (stored.length === 0) {
            listEl.innerHTML = `
                <div class="text-center py-4 bg-slate-50 dark:bg-slate-800 rounded-xl border border-dashed border-slate-200 dark:border-slate-700 text-xs text-slate-500">
                    <i data-lucide="inbox" class="w-6 h-6 mx-auto mb-1 text-slate-400"></i>
                    No custom corridors cached yet. Tap "Save Current Route" or choose a corridor below.
                </div>
            `;
            lucide.createIcons();
            return;
        }
        listEl.innerHTML = stored.map(entry => `
            <div class="flex items-center justify-between p-2.5 bg-slate-50 dark:bg-slate-800/80 rounded-xl border border-slate-200 dark:border-slate-700 text-xs">
                <div class="min-w-0 pr-2">
                    <div class="font-bold text-slate-900 dark:text-slate-100 truncate">${entry.title}</div>
                    <div class="text-[10px] text-slate-500 flex items-center gap-2">
                        <span>${entry.distance} • ${entry.duration}</span>
                        <span class="text-emerald-600 font-bold">${entry.safetyScore}</span>
                        <span>Saved: ${entry.savedAt}</span>
                    </div>
                </div>
                <div class="flex items-center gap-1.5 shrink-0">
                    <button onclick="loadCachedCorridor('${entry.id}')" class="px-2.5 py-1 bg-emerald-600 hover:bg-emerald-700 text-white rounded-lg text-[11px] font-bold shadow-xs transition btn-press">
                        Open
                    </button>
                    <button onclick="deleteCachedCorridor('${entry.id}')" class="p-1 text-slate-400 hover:text-red-500 rounded-lg transition" title="Delete Saved Corridor">
                        <i data-lucide="trash-2" class="w-3.5 h-3.5"></i>
                    </button>
                </div>
            </div>
        `).join('');
        lucide.createIcons();
    } catch (e) {
        listEl.innerHTML = '';
    }
}

function loadCachedCorridor(cacheId) {
    try {
        const stored = JSON.parse(localStorage.getItem('ner_cached_routes') || '[]');
        const entry = stored.find(e => e.id === cacheId);
        if (entry && entry.routes && entry.routes.length > 0) {
            const origInput = document.getElementById('originInput');
            const destInput = document.getElementById('destinationInput');
            if (origInput) origInput.value = entry.origin;
            if (destInput) destInput.value = entry.destination;

            const gmapOrig = document.getElementById('gmapOriginText');
            const gmapDest = document.getElementById('gmapDestText');
            if (gmapOrig) gmapOrig.innerText = entry.origin;
            if (gmapDest) gmapDest.innerText = entry.destination;

            const corridorTitle = document.getElementById('passCorridorTitle');
            if (corridorTitle) corridorTitle.innerText = `${entry.origin} to ${entry.destination}`;

            activeComputedRoutes = entry.routes;
            selectedRouteId = activeComputedRoutes[0].id;
            navigateTo('results');
            renderRouteCards();
            initOrUpdateMap();
            updatePassModalData(activeComputedRoutes[0]);
            renderElevationProfile(activeComputedRoutes[0]);
            renderMonthlyHazardGraph(activeComputedRoutes[0]);
            renderRoutePois(activeComputedRoutes[0]);
            closeOfflineCenterModal();
        }
    } catch (e) {}
}

function deleteCachedCorridor(cacheId) {
    try {
        let stored = JSON.parse(localStorage.getItem('ner_cached_routes') || '[]');
        stored = stored.filter(e => e.id !== cacheId);
        localStorage.setItem('ner_cached_routes', JSON.stringify(stored));
        renderSavedOfflineRoutesList();
    } catch (e) {}
}

function quickLoadOfflineCorridor(originName, destName) {
    const origInput = document.getElementById('originInput');
    const destInput = document.getElementById('destinationInput');
    if (origInput) origInput.value = originName;
    if (destInput) destInput.value = destName;

    const cached = getCachedRoute(originName, destName);
    if (cached && cached.length > 0) {
        const gmapOrig = document.getElementById('gmapOriginText');
        const gmapDest = document.getElementById('gmapDestText');
        if (gmapOrig) gmapOrig.innerText = originName;
        if (gmapDest) gmapDest.innerText = destName;

        const corridorTitle = document.getElementById('passCorridorTitle');
        if (corridorTitle) corridorTitle.innerText = `${originName} to ${destName}`;

        activeComputedRoutes = cached;
        selectedRouteId = activeComputedRoutes[0].id;
        navigateTo('results');
        renderRouteCards();
        initOrUpdateMap();
        updatePassModalData(activeComputedRoutes[0]);
        renderElevationProfile(activeComputedRoutes[0]);
        renderMonthlyHazardGraph(activeComputedRoutes[0]);
        renderRoutePois(activeComputedRoutes[0]);
    } else {
        executeRouteComputation(originName, destName);
    }
    closeOfflineCenterModal();
}

document.addEventListener('DOMContentLoaded', () => {
    const savedLang = localStorage.getItem('ner_selected_lang') || 'en';
    changeLanguage(savedLang);
    lucide.createIcons();
    initUserSession();
    if ('serviceWorker' in navigator) {
        navigator.serviceWorker.register('sw.js').catch(() => {});
    }
    window.addEventListener('online', () => {
        if (!isSimulatedOffline) updateNetworkStatus(true);
    });
    window.addEventListener('offline', () => {
        updateNetworkStatus(false);
    });
    updateNetworkStatus(navigator.onLine);

    const savedTheme = localStorage.getItem('ner_theme');
    if (savedTheme === 'dark') {
        document.body.classList.add('dark');
        const icon = document.getElementById('themeToggleIcon');
        const text = document.getElementById('themeToggleText');
        if (icon) icon.setAttribute('data-lucide', 'sun');
        if (text) text.innerText = 'Light';
        lucide.createIcons();
    }
    document.addEventListener('click', (e) => {
        const origDrop = document.getElementById('originAutocomplete');
        const destDrop = document.getElementById('destAutocomplete');
        if (origDrop && !origDrop.contains(e.target) && e.target.id !== 'originInput') {
            origDrop.classList.add('hidden');
        }
        if (destDrop && !destDrop.contains(e.target) && e.target.id !== 'destinationInput') {
            destDrop.classList.add('hidden');
        }
        const userMenu = document.getElementById('userDropdownMenu');
        const userBtn = document.getElementById('headerUserBtn');
        if (userMenu && !userMenu.contains(e.target) && userBtn && !userBtn.contains(e.target)) {
            userMenu.classList.add('hidden');
        }
    });
    document.addEventListener('keydown', (e) => {
        if (e.key === 'Escape') {
            closeDetailsModal();
            closeMethodologyModal();
            closeOfflinePassModal();
            closeSosModal();
            closeLoginModal();
            closeOfflineCenterModal();
            const origDrop = document.getElementById('originAutocomplete');
            const destDrop = document.getElementById('destAutocomplete');
            if (origDrop) origDrop.classList.add('hidden');
            if (destDrop) destDrop.classList.add('hidden');
            const userMenu = document.getElementById('userDropdownMenu');
            if (userMenu) userMenu.classList.add('hidden');
        }
    });
});
